cd /home/user/wt/benny && python3 - <<'EOF'
p='src/characters/benny/benny20.ts'
s=open(p).read()
old='''/** colour factors (LINEAR multipliers on the knit / felt maps, solved like the fur) + knit normal strength */
const MAT20 = {
  crown: lin('ccol', [0.78, 0.78, 0.7]),
  brim: lin('rcol', [0.67, 0.75, 0.57]),
  star: lin('scol', [0.34, 0.75, 1.0]),
  crownN: n('kcn', 2.0),
  brimN: n('kbn', 2.5),
};'''
new='''/** colour factors (LINEAR multipliers on the knit / felt maps, solved like the fur) + knit normal strength.
 *  r23 step 1: the `knit_mode: chain` maps (tools/benny20/knit.py, vertical rib cords, cream light stripes) carry their
 *  colour solved through the 04 light + post chain, so the knit factors are neutral. */
const MAT20 = {
  crown: lin('ccol', [1, 1, 1]),
  brim: lin('rcol', [1, 1, 1]),
  star: lin('scol', [0.34, 0.75, 1.0]),
  crownN: n('kcn', 2.0),
  brimN: n('kbn', 2.0),
};

/** r23 step 1: per-screen knit exposure (LINEAR multipliers on the crown / cuff colour, like EXPO20 for the fur) — the
 *  approved 05–08 paint the beanie ≈ 1.5× brighter than the game lights it there (white stripes, bright violet); a little
 *  more green / less blue keeps the light stripes CREAM instead of lavender. Applied only with `b20knit=1&b20expo=1`;
 *  overridable `&b20k0N=r,g,b`. Unlisted screens (04): 1. */
export const KNITX20: Record<string, [number, number, number]> = {
  '05': lin('k05', [1.5, 1.6, 1.5]),
  '06': lin('k06', [1.6, 1.8, 1.45]),
  '07': lin('k07', [1.6, 1.7, 1.6]),
  '08': lin('k08', [1.65, 1.8, 1.6]),
};'''
assert old in s; s=s.replace(old,new)
old2='''  // procedural knit maps: opt-in `&b20knit=1` until they beat benny05's approved-pixel beanie maps (kept by default)
  if (n('knit', 0) > 0) {
    knit('hat_crown', 'crown.png', 'crown_n.png', MAT20.crown, MAT20.crownN);
    knit('hat_brim', 'brim.png', 'brim_n.png', MAT20.brim, MAT20.brimN);
  }'''
new2='''  // procedural knit maps: opt-in `&b20knit=1` until they beat benny05's approved-pixel beanie maps (kept by default)
  const KNIT_ON = n('knit', 0) > 0;
  if (KNIT_ON) {
    knit('hat_crown', 'crown.png', 'crown_n.png', MAT20.crown, MAT20.crownN);
    knit('hat_brim', 'brim.png', 'brim_n.png', MAT20.brim, MAT20.brimN);
  }
  const knitMats = KNIT_ON && EXPO_ON
    ? ['hat_crown', 'hat_brim']
        .map((nm) => (get(nm) as THREE.Mesh | undefined)?.material as THREE.MeshStandardMaterial | undefined)
        .filter((m): m is THREE.MeshStandardMaterial => !!m?.map)
        .map((m) => ({ m, base: m.color.clone() }))
    : [];'''
assert old2 in s; s=s.replace(old2,new2)
old3='''  const cur = new THREE.Vector3(1, 1, 1);
  const tgt = new THREE.Vector3();'''
new3='''  const cur = new THREE.Vector3(1, 1, 1);
  const tgt = new THREE.Vector3();
  const kcur = new THREE.Vector3(1, 1, 1);
  const ktgt = new THREE.Vector3();'''
assert old3 in s; s=s.replace(old3,new3)
old4='''    if (first || jumped) { cur.copy(tgt); first = false; } else cur.lerp(tgt, 1 - Math.exp(-dt * 3));
    for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);'''
new4='''    const ke = (stage && KNITX20[stage]) || [1, 1, 1];
    ktgt.set(ke[0], ke[1], ke[2]);
    if (first || jumped) { cur.copy(tgt); kcur.copy(ktgt); first = false; } else {
      cur.lerp(tgt, 1 - Math.exp(-dt * 3));
      kcur.lerp(ktgt, 1 - Math.exp(-dt * 3));
    }
    for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);
    for (const { m, base } of knitMats) m.color.setRGB(base.r * kcur.x, base.g * kcur.y, base.b * kcur.z);'''
assert old4 in s; s=s.replace(old4,new4)
s=s.replace("(window as unknown as { __b20?: unknown }).__b20 = { scene, furs, hat, pom, star, HAT20, LOCK20, EXPO20, expo, screenBox };",
 "(window as unknown as { __b20?: unknown }).__b20 = { scene, furs, hat, pom, star, HAT20, LOCK20, EXPO20, expo, KNITX20, knitMats, screenBox };")
open(p,'w').write(s)
EOF
grep -n "knitMats\|KNITX20" src/characters/benny/benny20.ts | head; npx tsc --noEmit -p . 2>&1 | head -10

