cd /home/user/wt/benny && python3 - <<'EOF'
p='src/characters/benny/benny20.ts'
s=open(p).read()
old=s[s.index("/** r23 step 1: per-screen knit exposure"):s.index("const T = (f: string)")]
new='''/** r23 step 1: per-screen knit exposure, like EXPO20 for the fur. The approved 05–08 paint the beanie ≈ 1.5× brighter
 *  than the game lights it there (white stripes, bright violet), and each screen's light tints it differently, so the
 *  violet yarn (`v`) and the light CREAM yarn (`w`) get their own LINEAR multipliers (knit shader: the map texel's g / b
 *  ratio tells the two yarns apart). Solved per screen against the approved hat (violet median) and a cream target for
 *  the light stripes (not lavender). Applied only with `b20knit=1&b20expo=1`; overridable `&b20kv0N=r,g,b` /
 *  `&b20kw0N=r,g,b`. Unlisted screens (04): 1. */
export const KNITX20: Record<string, { v: [number, number, number]; w: [number, number, number] }> = {
  '05': { v: lin('kv05', [1.3, 1.3, 1.85]), w: lin('kw05', [1.5, 1.6, 1.5]) },
  '06': { v: lin('kv06', [1.65, 1.8, 1.42]), w: lin('kw06', [1.6, 2.05, 1.45]) },
  '07': { v: lin('kv07', [1.6, 0.9, 1.86]), w: lin('kw07', [1.6, 1.7, 1.6]) },
  '08': { v: lin('kv08', [1.94, 2.0, 2.47]), w: lin('kw08', [2.6, 4.2, 2.8]) },
};

'''
s=s.replace(old,new)
old2='''    mat.roughness = 0.92;
    mat.metalness = 0;
    mat.needsUpdate = true;
    m.material = mat;
  };'''
new2='''    mat.roughness = 0.92;
    mat.metalness = 0;
    // per-yarn exposure (KNITX20): violet texels (g ≪ b) × uKnitV, light cream texels (g ≈ b) × uKnitW
    const uKnitV = { value: new THREE.Vector3(1, 1, 1) };
    const uKnitW = { value: new THREE.Vector3(1, 1, 1) };
    mat.userData.knitU = { uKnitV, uKnitW };
    mat.onBeforeCompile = (sh) => {
      sh.uniforms.uKnitV = uKnitV;
      sh.uniforms.uKnitW = uKnitW;
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', '#include <common>\\nuniform vec3 uKnitV;\\nuniform vec3 uKnitW;')
        .replace('#include <map_fragment>', `#include <map_fragment>
#ifdef USE_MAP
  diffuseColor.rgb *= mix(uKnitV, uKnitW, smoothstep(0.3, 0.7, sampledDiffuseColor.g / max(sampledDiffuseColor.b, 0.01)));
#endif`);
    };
    mat.customProgramCacheKey = () => 'benny20knit';
    mat.needsUpdate = true;
    m.material = mat;
  };'''
assert old2 in s; s=s.replace(old2,new2)
old3='''        .map((m) => ({ m, base: m.color.clone() }))
    : [];'''
new3='''        .map((m) => m.userData.knitU as { uKnitV: { value: THREE.Vector3 }; uKnitW: { value: THREE.Vector3 } })
    : [];'''
assert old3 in s; s=s.replace(old3,new3)
old4='''  const kcur = new THREE.Vector3(1, 1, 1);
  const ktgt = new THREE.Vector3();'''
new4='''  const kvCur = new THREE.Vector3(1, 1, 1);
  const kwCur = new THREE.Vector3(1, 1, 1);
  const kvTgt = new THREE.Vector3();
  const kwTgt = new THREE.Vector3();'''
assert old4 in s; s=s.replace(old4,new4)
old5='''    const ke = (stage && KNITX20[stage]) || [1, 1, 1];
    ktgt.set(ke[0], ke[1], ke[2]);
    if (first || jumped) { cur.copy(tgt); kcur.copy(ktgt); first = false; } else {
      cur.lerp(tgt, 1 - Math.exp(-dt * 3));
      kcur.lerp(ktgt, 1 - Math.exp(-dt * 3));
    }
    for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);
    for (const { m, base } of knitMats) m.color.setRGB(base.r * kcur.x, base.g * kcur.y, base.b * kcur.z);'''
new5='''    const ke = (stage && KNITX20[stage]) || { v: [1, 1, 1], w: [1, 1, 1] };
    kvTgt.set(...ke.v);
    kwTgt.set(...ke.w);
    if (first || jumped) { cur.copy(tgt); kvCur.copy(kvTgt); kwCur.copy(kwTgt); first = false; } else {
      const a = 1 - Math.exp(-dt * 3);
      cur.lerp(tgt, a);
      kvCur.lerp(kvTgt, a);
      kwCur.lerp(kwTgt, a);
    }
    for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);
    for (const k of knitMats) { k.uKnitV.value.copy(kvCur); k.uKnitW.value.copy(kwCur); }'''
assert old5 in s; s=s.replace(old5,new5)
open(p,'w').write(s)
EOF
npx tsc --noEmit -p . 2>&1 | head; sed -n 140,160p src/characters/benny/benny20.ts

